contrast_ratio <- function(fg,bg) { lum<-function(hex){rgb<-col2rgb(hex)/255; rgb<-ifelse(rgb<=.04045,rgb/12.92,((rgb+.055)/1.055)^2.4); sum(rgb*c(.2126,.7152,.0722))}; vals<-sort(c(lum(fg),lum(bg))); (vals[2]+.05)/(vals[1]+.05) }
accessibility_ui <- function(id) { ns<-NS(id); lab_section(c("Check text and background contrast.","Interpret a ratio using WCAG thresholds.","Remember that contrast alone does not establish accessibility."),tagList(p("Experiment · Adjust a text and background colour."), fluidRow(column(6, textInput(ns("fg"),"Text colour (hex)","#202522"), textInput(ns("bg"),"Background colour (hex)","#FFFFFF")), column(6, numericInput(ns("size"),"Text size in points",16,min=8,max=72), uiOutput(ns("result")))), div(class="mt-3 p-4 border rounded", uiOutput(ns("sample")))),"What other barriers could remain even if the contrast ratio passes?") }
accessibility_server <- function(id) { moduleServer(id,function(input,output,session){ valid<-reactive({grepl("^#[0-9A-Fa-f]{6}$",input$fg)&&grepl("^#[0-9A-Fa-f]{6}$",input$bg)}); ratio<-reactive({req(valid());contrast_ratio(input$fg,input$bg)}); output$result<-renderUI({if(!valid()) return(div(class="alert alert-warning","Enter colours as six-digit hex values, e.g. #202522.")); r<-ratio(); level<-if(r>=7) "Passes AAA for normal text" else if(r>=4.5) "Passes AA for normal text" else if(r>=3) "Passes AA for large text only" else "Below WCAG AA thresholds"; div(class=if(r>=4.5) "alert alert-success" else "alert alert-warning",tags$strong(sprintf("%.2f:1",r)),br(),level,br(),span(class="footnote","Automated estimate; verify in context."))}); output$sample<-renderUI({if(!valid()) return("Preview appears when both colours are valid."); div(style=paste0("color:",input$fg,";background:",input$bg,";font-size:",input$size,"pt"),"Readable interface text should remain legible across contexts.")}) }) }
